static const UiGlyph kGlyphs[] = {
  { "A", 30, 30, kA },
  { "B", 30, 30, kB },
  { "X", 30, 30, kX },
  { "Y", 30, 30, kY },
  { "BACK", 32, 30, kBACK },
  { "START", 33, 30, kSTART },
  { "LB", 57, 24, kLB },
  { "RB", 57, 24, kRB },
  { "LT", 17, 32, kLT },
  { "RT", 17, 32, kRT },
  { "LS", 29, 30, kLS },
  { "RS", 29, 30, kRS },
  { "DPAD", 30, 30, kDPAD },
  { 0, 0, 0, 0 }
};

const UiGlyph *uiGlyph(const char *name)
{
  for (const UiGlyph *g = kGlyphs; g->name; g++)
    if (strcmp(g->name, name) == 0)
      return g;
  return 0;
}
